function validate([groups, nums]) {
  if (!Array.isArray(groups) || groups.length < 1 || groups.length > 1000) return 'groups needs 1 to 1000 arrays.';
  let total = 0;
  for (const group of groups) {
    if (!Array.isArray(group) || group.length < 1) return 'Every group needs at least one value.';
    total += group.length;
    if (group.some(v => !Number.isInteger(v) || v < -10000000 || v > 10000000)) return 'Values are integers between -10^7 and 10^7.';
  }
  if (total > 1000) return 'The groups hold at most 1000 values in total.';
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 1000) return 'nums needs 1 to 1000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < -10000000 || v > 10000000)) return 'Values are integers between -10^7 and 10^7.';
  return null;
}

