function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const alphabet = large ? (rand() < 0.5 ? 2 : 10000000) : int(1, 3);
  const value = () => alphabet === 10000000 ? int(-10000000, 10000000) : int(0, alphabet);
  const groupCount = large ? int(1, 60) : int(1, 3);
  const groups = [];
  let budget = large ? int(200, 900) : 0;
  for (let g = 0; g < groupCount; g++) {
    const len = large ? Math.max(1, Math.min(budget - (groupCount - g - 1), int(1, Math.max(1, Math.floor(2 * budget / (groupCount - g)))))) : int(1, 3);
    if (large) budget -= len;
    groups.push(Array.from({ length: len }, value));
  }
  const limit = large ? 1000 : int(1, 12);
  let nums;
  if (rand() < 0.65) {
    // Embed the groups in order with random filler, then maybe break one value.
    const total = groups.reduce((sum, group) => sum + group.length, 0);
    let spare = Math.max(0, limit - total);
    nums = [];
    for (const group of groups) {
      const gap = int(0, Math.min(spare, large ? 40 : 2));
      spare -= gap;
      for (let i = 0; i < gap; i++) nums.push(value());
      nums.push(...group);
    }
    while (spare-- > 0 && rand() < (large ? 0.999 : 0.5)) nums.push(value());
    if (rand() < 0.4) nums[int(0, nums.length - 1)] = value();
    if (nums.length > 1000) nums = nums.slice(0, 1000);
  } else {
    nums = Array.from({ length: limit }, value);
  }
  return [groups, nums];
}
